import type { BehaviorStepContext } from '@thirdlight/runtime';
import { drift } from './util';

export default {
  prepare() {
    return { t: 0 };
  },
  instantiate(prepared: unknown, inst: { properties: { speed: number } }) {
    return { t: 0, speed: inst.properties.speed };
  },
  step(state: { t: number; speed: number }, ctx: BehaviorStepContext) {
    state.t += 1;
    ctx.emit({ kind: 'control_move', value: drift(state.t, state.speed) });
  },
  dispose() {},
};

export function drift(t: number, speed: number): number {
  const wobble = ((t % 10) - 5) / 100;
  return Math.max(-1, Math.min(1, speed / 10 + wobble));
}
